  ('foundation:BrazilianNFSe', 'rdfs:comment', NULL, 'Brazilian electronic service invoice (Nota Fiscal de Serviço Eletrônica)', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 117, 0, 0),
