  ('foundation:hasWorkLocationAddress', 'rdfs:comment', NULL, 'Links a service contract to a specific physical address where work is performed (use alongside workLocation string for classifications)', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 178, 0, 0),
  ('foundation:hasWorkLocationAddress', 'rdfs:domain', 'foundation:ServiceContract', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 178, 0, 0),
  ('foundation:hasWorkLocationAddress', 'rdfs:label', NULL, 'endereço de trabalho', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 101, 0, 0),
