  ('qudt:DataEncoding', 'rdfs:comment', NULL, '<p><em>Data Encoding</em> expresses the properties that specify how data is represented at the bit and byte level. These properties are applicable to describing raw data.</p>', 'rdf:HTML', NULL, 'literal', NULL, NULL, NULL, 1, 201, 0, 0),
  ('qudt:DataEncoding', 'rdfs:isDefinedBy', 'http://qudt.org/2.1/schema/qudt', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 201, 0, 0),
