  ('qudt:LogarithmicUnit', 'foundation:lastUpdatedAt', NULL, '2026-03-04T04:10:29Z', 'xsd:dateTime', NULL, 'literal', NULL, NULL, NULL, 1, 208, 0, 0),
  ('qudt:LogarithmicUnit', 'rdf:type', 'owl:Class', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 201, 0, 0),
  ('qudt:LogarithmicUnit', 'rdfs:comment', NULL, 'Logarithmic units are abstract mathematical units that can be used to express any quantities (physical or mathematical) that are defined on a logarithmic scale, that is, as being proportional to the value of a logarithm function. Examples of logarithmic units include common units of information and entropy, such as the bit, and the byte, as well as units of relative signal strength magnitude such as the decibel.', 'rdf:HTML', NULL, 'literal', NULL, NULL, NULL, 1, 201, 0, 0),
  ('qudt:LogarithmicUnit', 'rdfs:isDefinedBy', 'http://qudt.org/2.1/schema/qudt', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 201, 0, 0),
