  ('qudt:ScalarDatatype', 'foundation:lastUpdatedAt', NULL, '2026-03-04T04:10:29Z', 'xsd:dateTime', NULL, 'literal', NULL, NULL, NULL, 1, 208, 0, 0),
  ('qudt:ScalarDatatype', 'http://purl.org/dc/terms/description', NULL, 'Scalar data types are those that have a single value. The permissible values are defined over a domain that may be integers, float, character or boolean. Often a scalar data type is referred to as a primitive data type.', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 201, 0, 0),
