  ('qudt:Scale', 'rdf:type', 'owl:Class', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 201, 0, 0),
  ('qudt:Scale', 'rdfs:comment', NULL, 'Scales (also called "scales of measurement" or "levels of measurement")  are expressions that typically refer to the theory of scale types.', 'rdf:HTML', NULL, 'literal', NULL, NULL, NULL, 1, 201, 0, 0),
  ('qudt:Scale', 'rdfs:isDefinedBy', 'http://qudt.org/2.1/schema/qudt', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 201, 0, 0),
