  ('qudt:ScaleType', 'foundation:lastUpdatedAt', NULL, '2026-03-04T04:10:29Z', 'xsd:dateTime', NULL, 'literal', NULL, NULL, NULL, 1, 208, 0, 0),
  ('qudt:ScaleType', 'qudt:plainTextDescription', NULL, 'Scales, or scales of measurement (or categorization) provide ways of quantifying measurements, values and other enumerated values according to a normative frame of reference.  Four different types of scales are typically used. These are interval, nominal, ordinal and ratio scales.', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 201, 0, 0),
