  ('qudt:SolidAngleUnit', 'foundation:lastUpdatedAt', NULL, '2026-03-04T04:10:29Z', 'xsd:dateTime', NULL, 'literal', NULL, NULL, NULL, 1, 208, 0, 0),
  ('qudt:SolidAngleUnit', 'http://purl.org/dc/terms/description', NULL, 'The solid angle subtended by a surface S is defined as the surface area of a unit sphere covered by the surface S''s projection onto the sphere. A solid angle is related to the surface of a sphere in the same way an ordinary angle is related to the circumference of a circle. Since the total surface area of the unit sphere is 4*pi, the measure of solid angle will always be between 0 and 4*pi.', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 201, 0, 0),
  ('qudt:SolidAngleUnit', 'rdf:type', 'owl:Class', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 201, 0, 0),
  ('qudt:SolidAngleUnit', 'rdfs:isDefinedBy', 'http://qudt.org/2.1/schema/qudt', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 201, 0, 0),
  ('qudt:SolidAngleUnit', 'rdfs:label', NULL, 'Solid Angle Unit', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 201, 0, 0),
