  ('unit:BARAD', 'foundation:lastUpdatedAt', NULL, '2026-03-04T04:10:29Z', 'xsd:dateTime', NULL, 'literal', NULL, NULL, NULL, 1, 208, 0, 0),
  ('unit:BARAD', 'http://purl.org/dc/terms/description', NULL, 'A barad is a dyne per square centimetre ($dyn \cdot cm^{-2}$), and is equal to $0.1 Pa $ ($1 \, micro \, bar$, $0.000014504 \, p.s.i.$). Note that this is precisely the microbar, the confusable bar being related in size to the normal atmospheric pressure, at $100\,dyn \cdot cm^{-2}$. Accordingly barad was not abbreviated, so occurs prefixed as in $cbarad = centibarad$. Despite being the coherent unit for pressure in c.g.s., barad was probably much less common than the non-coherent bar. Barad is sometimes called $barye$, a name also used for $bar$.', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:BARAD', 'qudt:applicableSystem', 'http://qudt.org/vocab/sou/CGS', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:BARAD', 'qudt:conversionMultiplier', NULL, '0.1', 'xsd:decimal', NULL, 'literal', 0.1, NULL, NULL, 1, 202, 0, 0),
  ('unit:BARAD', 'qudt:conversionMultiplierSN', NULL, '0.1', 'xsd:decimal', NULL, 'literal', 0.1, NULL, NULL, 1, 202, 0, 0),
  ('unit:BARAD', 'qudt:exactMatch', 'unit:BARYE', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
