  ('unit:BARAD', 'qudt:hasQuantityKind', 'http://qudt.org/vocab/quantitykind/VaporPressure', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:BARAD', 'qudt:symbol', NULL, 'Ba', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
