  ('unit:C_Stat', 'foundation:lastUpdatedAt', NULL, '2026-03-04T04:10:29Z', 'xsd:dateTime', NULL, 'literal', NULL, NULL, NULL, 1, 208, 0, 0),
  ('unit:C_Stat', 'http://purl.org/dc/terms/description', NULL, 'The statcoulomb ($statC$) or franklin ($Fr$) or electrostatic unit of charge ($esu$) is the physical unit for electrical charge used in the centimetre-gram-second system of units (cgs) and Gaussian units. It is a derived unit given by $1\ statC = 1\ g\ cm\ s = 1\ erg\ cm$. The SI system of units uses the coulomb (C) instead. The conversion between C and statC is different in different contexts. The number 2997924580 is 10 times the value of the speed of light expressed in meters/second, and the conversions are exact except where indicated. The coulomb is an extremely large charge rarely encountered in electrostatics, while the statcoulomb is closer to everyday charges.', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'qudt:applicableSystem', 'http://qudt.org/vocab/sou/CGS', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'qudt:applicableSystem', 'http://qudt.org/vocab/sou/CGS-ESU', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'qudt:conversionMultiplier', NULL, '0.00000000033356409519815207', 'xsd:decimal', NULL, 'literal', 0.00000000033356409519815207, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'qudt:conversionMultiplierSN', NULL, '0.00000000033356409519815207', 'xsd:decimal', NULL, 'literal', 0.00000000033356409519815207, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'qudt:dbpediaMatch', NULL, 'http://dbpedia.org/resource/Statcoulomb', 'xsd:anyURI', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'qudt:derivedUnitOfSystem', 'http://qudt.org/vocab/sou/CGS-ESU', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'qudt:exactMatch', 'unit:FR', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'qudt:hasDimensionVector', 'http://qudt.org/vocab/dimensionvector/A0E1L0I0M0H0T1D0', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'qudt:hasQuantityKind', 'http://qudt.org/vocab/quantitykind/ElectricCharge', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'qudt:informativeReference', NULL, 'http://en.wikipedia.org/wiki/Statcoulomb?oldid=492664360', 'xsd:anyURI', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'qudt:latexDefinition', NULL, '$1 C \leftrightarrow 2997924580 statC \approx 3.00 \times 10^9 statC,\ 1 \hspace{0.3pc} statC \leftrightarrow \hspace{0.3pc} \approx 3.34 \times 10^{-10} C$ for electric charge.', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'qudt:latexDefinition', NULL, '$1 C \leftrightarrow 4 \pi \times 2997924580 statC \approx 3.77 \times 10^{10} statC,\ 1 \hspace{0.3pc} statC \leftrightarrow \hspace{0.2pc} \approx 2.6 \times 10^{-11} C$ for electric flux $\Phi_D$', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'qudt:latexDefinition', NULL, '$1 C/m \leftrightarrow 4 \pi \times 2997924580 \times 10^{-4} statC/cm \approx 3.77 \times 10^6 statC/cm,\ 1 \hspace{0.3pc} statC/cm \leftrightarrow \hspace{0.3pc} \approx 2.65 \times 10^{-7} C/m$ for electric displacement field $D$.', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'qudt:omUnit', 'http://www.ontology-of-units-of-measure.org/resource/om-2/statcoulomb', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'qudt:symbol', NULL, 'statC', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:C_Stat', 'rdf:type', 'qudt:Unit', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
