  ('unit:DEG_C', 'qudt:conversionMultiplier', NULL, '1', 'xsd:decimal', NULL, 'literal', 1, NULL, NULL, 1, 202, 0, 0),
  ('unit:DEG_C', 'qudt:conversionMultiplierSN', NULL, '1', 'xsd:decimal', NULL, 'literal', 1, NULL, NULL, 1, 202, 0, 0),
  ('unit:DEG_C', 'qudt:conversionOffset', NULL, '273.15', 'xsd:decimal', NULL, 'literal', 273.15, NULL, NULL, 1, 202, 0, 0),
  ('unit:DEG_C', 'qudt:conversionOffsetSN', NULL, '273.15', 'xsd:decimal', NULL, 'literal', 273.15, NULL, NULL, 1, 202, 0, 0),
  ('unit:DEG_C', 'qudt:dbpediaMatch', NULL, 'http://dbpedia.org/resource/Celsius', 'xsd:anyURI', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
