  ('unit:EarthMass', 'foundation:lastUpdatedAt', NULL, '2026-03-04T04:10:29Z', 'xsd:dateTime', NULL, 'literal', NULL, NULL, NULL, 1, 208, 0, 0),
  ('unit:EarthMass', 'http://purl.org/dc/terms/description', NULL, 'Earth mass ($M_{\oplus}$) is the unit of mass equal to that of the Earth. In SI Units, $1 M_{\oplus} = 5.9722 \times 10^{24} kg$. Earth mass is often used to describe masses of rocky terrestrial planets. The four terrestrial planets of the Solar System, Mercury, Venus, Earth, and Mars, have masses of 0.055, 0.815, 1.000, and 0.107 Earth masses respectively.', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:EarthMass', 'qudt:conversionMultiplier', NULL, '5972190000000000000000000', 'xsd:decimal', NULL, 'literal', 5972190000000000000000000, NULL, NULL, 1, 202, 0, 0),
