  ('unit:J', 'qudt:hasQuantityKind', 'http://qudt.org/vocab/quantitykind/ThermalEnergy', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:J', 'qudt:iec61360Code', NULL, '0112/2///62720#UAA172', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:J', 'qudt:informativeReference', NULL, 'http://en.wikipedia.org/wiki/Joule?oldid=494340406', 'xsd:anyURI', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:J', 'qudt:informativeReference', NULL, 'https://cdd.iec.ch/cdd/iec62720/iec62720.nsf/Units/0112-2---62720%23UAA172', 'xsd:anyURI', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:J', 'qudt:latexDefinition', NULL, '$$\text{J}\ \equiv\ \text{joule}\ \equiv\ \text{CV}\ \equiv\ \text{coulomb.volt}\ \equiv\ \frac{\text{eV}}{1.602\ 10^{-19}}\ \equiv\ \frac{\text{electron.volt}}{1.602\ 10^{-19}}$$', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:J', 'qudt:omUnit', 'http://www.ontology-of-units-of-measure.org/resource/om-2/joule', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:J', 'qudt:plainTextDescription', NULL, 'The SI unit of work or energy, defined to be the work done by a force of one newton acting to move an object through a distance of one meter in the direction in which the force is applied. Equivalently, since kinetic energy is one half the mass times the square of the velocity, one joule is the kinetic energy of a mass of two kilograms moving at a velocity of 1 m/s. This is the same as 107 ergs in the CGS system, or approximately 0.737 562 foot-pound in the traditional English system. In other energy units, one joule equals about 9.478 170 x 10-4 Btu, 0.238 846 (small) calories, or 2.777 778 x 10-4 watt hour. The joule is named for the British physicist James Prescott Joule (1818-1889), who demonstrated the equivalence of mechanical and thermal energy in a famous experiment in 1843. ', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:J', 'qudt:siExactMatch', 'https://si-digital-framework.org/SI/units/joule', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0);
