  ('unit:M2-PER-SEC-BAR', 'qudt:iec61360Code', NULL, '0112/2///62720#UAB493', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:M2-PER-SEC-BAR', 'qudt:informativeReference', NULL, 'https://cdd.iec.ch/cdd/iec62720/iec62720.nsf/Units/0112-2---62720%23UAB493', 'xsd:anyURI', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
