  ('unit:MOHM', 'http://purl.org/dc/terms/description', NULL, '
  The $\textit{Mohm}$ is a unit of mechanical mobility for sound waves, being the reciprocal of the mechanical $ohm$ unit of impedance, i.e., for an acoustic medium, the ratio of the flux or volumic speed (area times particle speed) of the resulting waves through it to the effective sound pressure (i.e. force) causing them, the unit being qualified, according to the units used, as m.k.s. or c.g.s. 
  The mechanical ohm is defined as:
  $$Mohm \equiv 1\,dyn\cdot\,s\cdot cm^{-1} \text{ or } 10^{-3} N\cdot s\cdot m^{-1}$$.
  ', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:MOHM', 'qudt:applicableSystem', 'http://qudt.org/vocab/sou/CGS', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:MOHM', 'qudt:conversionMultiplier', NULL, '1000', 'xsd:decimal', NULL, 'literal', 1000, NULL, NULL, 1, 202, 0, 0),
  ('unit:MOHM', 'qudt:conversionMultiplierSN', NULL, '1000', 'xsd:decimal', NULL, 'literal', 1000, NULL, NULL, 1, 202, 0, 0),
  ('unit:MOHM', 'qudt:expression', NULL, '$mohm$', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:MOHM', 'qudt:hasDimensionVector', 'http://qudt.org/vocab/dimensionvector/A0E0L0I0M-1H0T1D0', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:MOHM', 'qudt:hasQuantityKind', 'http://qudt.org/vocab/quantitykind/MechanicalMobility', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:MOHM', 'qudt:informativeReference', NULL, 'http://www.oxfordreference.com/view/10.1093/acref/9780198605225.001.0001/acref-9780198605225-e-914', 'xsd:anyURI', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:MOHM', 'qudt:latexDefinition', NULL, '$1\:{mohm_{cgs}} = 1\:\frac {cm} {dyn.s}\: (=\:1\:\frac s g \:in\:base\:c.g.s.\:terms)$', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:MOHM', 'qudt:latexDefinition', NULL, '$1\:{mohm_{mks}} = 10^{3}\:\frac m {N.s}\:(=\:10^{3}\:   \frac s {kg}\:in\:base\:m.k.s.\:terms)$', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
