  ('unit:OHM_Stat', 'qudt:latexSymbol', NULL, '$stat\Omega$', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:OHM_Stat', 'qudt:omUnit', 'http://www.ontology-of-units-of-measure.org/resource/om-2/statohm', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
