  ('unit:PlanckEnergy', 'foundation:lastUpdatedAt', NULL, '2026-03-04T04:10:29Z', 'xsd:dateTime', NULL, 'literal', NULL, NULL, NULL, 1, 208, 0, 0),
  ('unit:PlanckEnergy', 'http://purl.org/dc/terms/description', NULL, 'In physics, the unit of energy in the system of natural units known as Planck units is called the Planck energy, denoted by $E_P$. $E_P$ is a derived, as opposed to basic, Planck unit. An equivalent definition is:$E_P = \hbar / T_P$ where $T_P$ is the Planck time. Also: $E_P = m_P c^2$ where $m_P$ is the Planck mass.', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:PlanckEnergy', 'qudt:applicableSystem', 'http://qudt.org/vocab/sou/PLANCK', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:PlanckEnergy', 'qudt:conversionMultiplier', NULL, '1956100000', 'xsd:decimal', NULL, 'literal', 1956100000, NULL, NULL, 1, 202, 0, 0),
  ('unit:PlanckEnergy', 'qudt:conversionMultiplierSN', NULL, '1956100000', 'xsd:decimal', NULL, 'literal', 1956100000, NULL, NULL, 1, 202, 0, 0),
  ('unit:PlanckEnergy', 'qudt:dbpediaMatch', NULL, 'http://dbpedia.org/resource/Planck_energy', 'xsd:anyURI', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:PlanckEnergy', 'qudt:derivedUnitOfSystem', 'http://qudt.org/vocab/sou/PLANCK', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:PlanckEnergy', 'qudt:hasDimensionVector', 'http://qudt.org/vocab/dimensionvector/A0E0L2I0M1H0T-2D0', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:PlanckEnergy', 'qudt:hasQuantityKind', 'http://qudt.org/vocab/quantitykind/Energy', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:PlanckEnergy', 'qudt:informativeReference', NULL, 'http://en.wikipedia.org/wiki/Planck_energy?oldid=493639955', 'xsd:anyURI', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:PlanckEnergy', 'qudt:latexDefinition', NULL, '$E_\rho = \sqrt{\frac{ \hbar c^5}{G}} \approx 1.936 \times 10^9 J \approx 1.22 \times 10^{28} eV \approx 0.5433 MWh$, where  $c$ is the speed of light in a vacuum, $\hbar$ is the reduced Planck''s constant, and $G$ is the gravitational constant.', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:PlanckEnergy', 'qudt:symbol', NULL, 'Eᵨ', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:PlanckEnergy', 'rdf:type', 'qudt:Unit', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
