  ('unit:PlanckEnergy', 'rdfs:label', NULL, 'Planck Energy', 'rdf:langString', 'en', 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:PlanckForce', 'foundation:lastUpdatedAt', NULL, '2026-03-04T04:10:29Z', 'xsd:dateTime', NULL, 'literal', NULL, NULL, NULL, 1, 208, 0, 0),
  ('unit:PlanckForce', 'http://purl.org/dc/terms/description', NULL, 'Planck force is the derived unit of force resulting from the definition of the base Planck units for time, length, and mass. It is equal to the natural unit of momentum divided by the natural unit of time.', 'rdf:HTML', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
