  ('unit:PlanckLength', 'qudt:hasQuantityKind', 'http://qudt.org/vocab/quantitykind/Length', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:PlanckLength', 'qudt:informativeReference', NULL, 'http://en.wikipedia.org/wiki/Planck_length?oldid=495093067', 'xsd:anyURI', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
