  ('unit:PlanckMass', 'qudt:informativeReference', NULL, 'http://en.wikipedia.org/wiki/Planck_mass?oldid=493648632', 'xsd:anyURI', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:PlanckMass', 'qudt:informativeReference', NULL, 'https://en.wikipedia.org/wiki/Planck_units', 'xsd:anyURI', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:PlanckMass', 'qudt:latexDefinition', NULL, '$m_P = \sqrt{\frac{ \hbar c^3}{G}} \approx 1.2209 \times 10^{19} GeV/c^2 = 2.17651(13) \times 10^{-8}$, where $c$ is the speed of light in a vacuum, $\hbar$ is the reduced Planck''s constant, and $G$ is the gravitational constant. The two digits enclosed by parentheses are the estimated standard error associated with the reported numerical value.', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
