  ('unit:SUSCEPTIBILITY_ELEC', 'foundation:lastUpdatedAt', NULL, '2026-03-04T04:10:29Z', 'xsd:dateTime', NULL, 'literal', NULL, NULL, NULL, 1, 208, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'foundation:lastUpdatedAt', NULL, '2026-03-04T04:10:29Z', 'xsd:dateTime', NULL, 'literal', NULL, NULL, NULL, 1, 208, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'http://purl.org/dc/terms/description', NULL, 'Electric susceptibility is a dimensionless proportionality constant that indicates the degree of polarization of a dielectric material in response to an applied electric field. Here P = epsilon_0 * chi_e * E. Where epsilon_0 is the electric permittivity of free space (electric constant), P is the polarization density of the material chi_e is the electric susceptibility and E is the electric field.', 'rdf:HTML', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'qudt:applicableSystem', 'http://qudt.org/vocab/sou/ASU', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'qudt:applicableSystem', 'http://qudt.org/vocab/sou/CGS', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'qudt:applicableSystem', 'http://qudt.org/vocab/sou/CGS-EMU', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'qudt:applicableSystem', 'http://qudt.org/vocab/sou/CGS-ESU', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'qudt:applicableSystem', 'http://qudt.org/vocab/sou/CGS-GAUSS', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'qudt:applicableSystem', 'http://qudt.org/vocab/sou/IMPERIAL', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
