  ('unit:SUSCEPTIBILITY_ELEC', 'qudt:conversionMultiplier', NULL, '1', 'xsd:decimal', NULL, 'literal', 1, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'qudt:conversionMultiplierSN', NULL, '1', 'xsd:decimal', NULL, 'literal', 1, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'qudt:hasDimensionVector', 'http://qudt.org/vocab/dimensionvector/A0E0L0I0M0H0T0D1', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'qudt:hasQuantityKind', 'http://qudt.org/vocab/quantitykind/Dimensionless', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'qudt:latexDefinition', NULL, '\chi_{\text{e}} = \frac{{\mathbf P}}{\varepsilon_0{\mathbf E}}', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'qudt:plainTextDescription', NULL, 'Electric susceptibility is a dimensionless proportionality constant that indicates the degree of polarization of a dielectric material in response to an applied electric field. Here P = epsilon_0 * chi_e * E. Where epsilon_0 is the electric permittivity of free space (electric constant), P is the polarization density of the material chi_e is the electric susceptibility and E is the electric field.', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'qudt:symbol', NULL, 'χ', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'rdf:type', 'qudt:DerivedUnit', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
