  ('unit:SUSCEPTIBILITY_ELEC', 'rdfs:isDefinedBy', 'http://qudt.org/2.1/vocab/unit', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_ELEC', 'rdfs:label', NULL, 'Electric Susceptibility Unit', 'rdf:langString', 'en', 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_MAG', 'foundation:lastUpdatedAt', NULL, '2026-03-04T04:10:29Z', 'xsd:dateTime', NULL, 'literal', NULL, NULL, NULL, 1, 208, 0, 0),
  ('unit:SUSCEPTIBILITY_MAG', 'foundation:lastUpdatedAt', NULL, '2026-03-04T04:10:29Z', 'xsd:dateTime', NULL, 'literal', NULL, NULL, NULL, 1, 208, 0, 0),
  ('unit:SUSCEPTIBILITY_MAG', 'http://purl.org/dc/terms/description', NULL, 'Magnetic susceptibility is a dimensionless proportionality constant that indicates the degree of magnetization of a material in response to an applied magnetic field. Here M = chi * H. Where M is the magnetization of the material (the magnetic dipole moment per unit volume), measured in amperes per meter, and H is the magnetic field strength, also measured in amperes per meter. Chi is therefore a dimensionless quantity.', 'rdf:HTML', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_MAG', 'qudt:applicableSystem', 'http://qudt.org/vocab/sou/ASU', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
