  ('unit:SUSCEPTIBILITY_MAG', 'qudt:hasQuantityKind', 'http://qudt.org/vocab/quantitykind/Dimensionless', NULL, NULL, NULL, 'iri', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_MAG', 'qudt:latexDefinition', NULL, '\chi_\text{v} = \frac{\mathbf{M}}{\mathbf{H}}', 'qudt:LatexString', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_MAG', 'qudt:plainTextDescription', NULL, 'Magnetic susceptibility is a dimensionless proportionality constant that indicates the degree of magnetization of a material in response to an applied magnetic field. Here M = chi * H. Where M is the magnetization of the material (the magnetic dipole moment per unit volume), measured in amperes per meter, and H is the magnetic field strength, also measured in amperes per meter. Chi is therefore a dimensionless quantity.', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
  ('unit:SUSCEPTIBILITY_MAG', 'qudt:symbol', NULL, 'χ', 'xsd:string', NULL, 'literal', NULL, NULL, NULL, 1, 202, 0, 0),
